Let $0<t\le1$. The time-$t$ end-point map relative to the vector fields
	$X_1,\dots,X_d\in\mathrm{Vec}(M)$ is the map $F^t_q:L^2([0,1],\mathbb{R}^d)\to M$ given by
	\begin{equation}\label{eq:endp}
		F^t_{q}(u)=q\circ\overrightarrow{\exp}\int_0^tX_{u(\tau)}\,d\tau .
	\end{equation}

\label{prop:essmin}
	Suppose that $Q^t\ge0$ on $u(t)^\perp\subset\mathbb{R}^d$ at every Lebesgue point of $u$. Then
	\[
		\mathrm{ess\,inf}_{t\in[0,1]}
		\left(\min_{w\in u(t)^\perp,\,|w|=1}Q^{t}(w)\right)\ge0 .
	\]

\label{prop:smooth}
	Under the Goh condition \eqref{eq:Goh_section} and the strong Legendre condition
	\eqref{eq:strongLeg}, the continuous representative of $u$ is smooth on $[0,1]$.

\label{prop:completion}
	The completion of $H^1([0,t],\mathbb{R}^d)$ with respect to $\|\cdot\|_{\mathcal H}$ is
	isometric to $\mathcal K:=\mathbb{R}^d\oplus L^2([0,t],\mathbb{R}^d)$.

\label{lem:conenorm}
	Let $\mathbf v=(v_1,v)\in L^2([0,t],\mathbb{R}^d)$ satisfy \eqref{eq:conepointwise}. Then
	\begin{equation}\label{eq:pointwisecone}
		\left|\mathbf v(\tau)\right|^2\le2\left|v_1(\tau)\right|\le4,
		\qquad\text{a.e. }\tau\in[0,t],
	\end{equation}
	and consequently
	\begin{equation}\label{eq:conenorm}
		\left\|\mathbf v\right\|_{L^2([0,t],\mathbb{R}^d)}^2\le2\left|V_1(t)\right|
		\le2\left\|\mathbf V\right\|_{\mathcal H},
		\qquad
		\left\|\mathbf v\right\|_{L^1([0,t],\mathbb{R}^d)}\le2t .
	\end{equation}

\label{lem:localization}
	Let $t\in(0,t_0]$ and let $\mathbf v\in L^2([0,t],\mathbb{R}^d)$ satisfy the constraint
	\eqref{eq:conepointwise}. Then the Cauchy problem \eqref{eq:perturbedode} has a unique
	absolutely continuous solution on $[0,t]$ and, with $L_0$ and $\delta$ as in
	Lemma~\ref{lem:adapted}(v),
	\begin{equation}\label{eq:noleave}
		\left|q_{\mathbf v}(\tau)\right|\le2L_0t<\delta,\qquad\tau\in[0,t].
	\end{equation}
	In particular $q_{\mathbf v}(\tau)$ stays in the translated set $\mathcal B$.

\label{lem:defect}
	There exists $C_Q>0$, independent of $t$, such that for every $t\in(0,t_0]$ and every
	variation $\mathbf v\in L^2([0,t],\mathbb{R}^d)$ satisfying \eqref{eq:conepointwise} one has
	\begin{equation}\label{eq:defectest}
		\left|G^t_{q(t)}(\mathbf v)-d_0G^t_{q(t)}(\mathbf v)\right|\le C_Q\,t\,\|\mathbf V\|_{\mathcal H} .
	\end{equation}

\label{prop:perturbedKer}
	There exists $C_0>0$, independent of $t\in(0,t_0]$, such that every variation
	$\mathbf v\in L^2([0,t],\mathbb{R}^d)$ satisfying \eqref{eq:conepointwise} obeys, for
	$i=1,\dots,d$,
	\begin{equation}\label{eq:perturbedkerest}
		|V_i(t)|\le\sqrt{C_0}\,\|V\|_{L^2([0,t],\mathbb{R}^{d-1})}
		+C_\eta\left|G^t_{q(t)}(\mathbf v)\right|
		+C_\eta C_Q\,t\,\|\mathbf V\|_{\mathcal H}.
	\end{equation}

\label{prop:perturbednorm}
	There exist $t_1\in(0,t_0]$ and constants $C_1,C_2>0$, all independent of $t$, such
	that for every $t\in(0,t_1]$ and every $\mathbf v$ satisfying \eqref{eq:conepointwise},
	\begin{equation}\label{eq:perturbednormequiv}
		\left\|\mathbf V\right\|_{\mathcal H}^2
		\le C_1^2\,\|V\|_{L^2([0,t],\mathbb{R}^{d-1})}^2
		+C_2^2\,\left|G^t_{q(t)}(\mathbf v)\right|^2 .
	\end{equation}

\label{thm:perturbedcoercivity}
	Assume the strong Legendre condition \eqref{eq:slg1} along the abnormal reference
	trajectory, with constant $c>0$. Then there exist $t_2\in(0,t_1]$ and constants
	$\gamma_*>0$, $C_3>0$, all independent of $t$, such that for every $t\in(0,t_2]$ and
	every variation $\mathbf v$ satisfying \eqref{eq:conepointwise},
	\begin{equation}\label{eq:perturbedcoercivity}
		\lambda(t)\widehat{H^t}\big(V(t),V\big)
		\ \ge\ \gamma_*\left\|\mathbf V\right\|_{\mathcal H}^2
		-C_3\left|G^t_{q(t)}(\mathbf v)\right|^2 .
	\end{equation}

\label{lem:cubicremainder}
	There exist constants $C_R,C_S>0$, independent of $t\in(0,t_2]$, such that the
	following holds. Let $t\in(0,t_2]$ and let $\mathbf v\in L^2([0,t],\mathbb{R}^d)$ satisfy the
	admissibility constraint \eqref{eq:conepointwise}. Then
	\begin{equation}\label{eq:exactexpansion}
		a_t\big(G^t_{q(t)}(\mathbf v)\big)
		=\frac12\,\lambda(t)\widehat{H^t}\big(V(t),V\big)+S^t(\mathbf v)+R^t(\mathbf v),
	\end{equation}
	where $a_t=\left\langle\ell_t,\cdot\right\rangle$ is the affine abnormal coordinate of
	Lemma~\ref{lem:adapted}(iii),
	\begin{equation}\label{eq:Sterm}
		S^t(\mathbf v):=\frac12\left(q(t)\circ W_{\mathbf v}\circ W_{\mathbf v}\right)a_t ,
		\qquad
		W_{\mathbf v}:=\int_0^tX^\tau_{\mathbf v(\tau)}\,d\tau ,
	\end{equation}
	and
	\begin{equation}\label{eq:remainderintegral}
		R^t(\mathbf v):=\int_{\Sigma_3(t)}\Big(q_{\mathbf v}(\tau_3)\circ X_{\mathbf v(\tau_3)}^{\tau_3}
		\circ X_{\mathbf v(\tau_2)}^{\tau_2}\circ X_{\mathbf v(\tau_1)}^{\tau_1}\Big)a_t
		\,d\tau_3d\tau_2d\tau_1 .
	\end{equation}
	Moreover
	\begin{equation}\label{eq:remainderestimate}
		\left|R^t(\mathbf v)\right|\le C_R\sqrt t\,\|\mathbf V\|_{\mathcal H}^2,
		\qquad
		\left|S^t(\mathbf v)\right|\le C_S\,\|\mathbf V\|_{\mathcal H}
		\left(\left|G^t_{q(t)}(\mathbf v)\right|+C_Q\,t\,\|\mathbf V\|_{\mathcal H}\right).
	\end{equation}

\label{thm:separation}
	Assume the Goh condition \eqref{eq:Goh_section} and the strong Legendre condition
	\eqref{eq:slg1} along the abnormal reference trajectory. Then there exist
	$t_*\in(0,t_2]$ and constants $\eta>0$, $C_4>0$, all independent of $t$, such that for
	every $t\in(0,t_*]$ and every variation $\mathbf v\in L^2([0,t],\mathbb{R}^d)$ satisfying the
	admissibility constraint \eqref{eq:conepointwise},
	\begin{equation}\label{eq:separation}
		\left\langle\ell_t,G^t_{q(t)}(\mathbf v)\right\rangle
		\ \ge\ \eta\left\|\mathbf V\right\|_{\mathcal H}^2
		-C_4\left|G^t_{q(t)}(\mathbf v)\right|^2 .
	\end{equation}
	In particular,
	\begin{equation}\label{eq:separationdist}
		C_\ell\left|G^t_{q(t)}(\mathbf v)\right|+C_4\left|G^t_{q(t)}(\mathbf v)\right|^2
		\ \ge\ \eta\left\|\mathbf V\right\|_{\mathcal H}^2 .
	\end{equation}

\label{cor:rigidity}
	Let $t\in(0,t_*]$ and let $\mathbf v$ satisfy \eqref{eq:conepointwise} together with
	$G^t_{q(t)}(\mathbf v)=0$, i.e.\ $F^t_q(u+\mathbf v)=q(t)$. Then $\mathbf v\equiv0$.
